// Package mime builds the message app/mailer/smtp.py's _build_mime builds, and
// the bytes smtplib puts in DATA for it.
//
// Every rule in here is Python's, not RFC 2047's own reading of itself: which
// of base64 and quoted-printable an encoded word uses, when a header folds,
// which transfer encoding a body gets, what a part's headers are and in which
// order. The RFC permits many spellings and a recipient's spam filter sees the
// one we send, so the one we send is the one that has been going out.
//
// The reference bytes are generated by scripts/python_mime_bytes.py from the
// app's own builder and smtplib's own flattening, and mime_bytes_test.go
// compares against them. Nothing here is "tidied": a different fold point is a
// different message.
package mime

import (
	"encoding/base64"
	"strings"
)

// qSafe is email._encoded_words._q_byte_map's identity range: a byte outside it
// becomes =XX, and a space becomes an underscore.
const qSafe = "!*+-/0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"

// encodeWord is email._encoded_words.encode: utf-8, and whichever of q and b is
// shorter -- except that q wins when it is up to five characters longer.
//
// That bias is why "Grüße" goes out quoted-printable and "Résumé — über 漢字"
// goes out base64, which looks arbitrary from outside and is the difference
// between our mail and mail that does not match what we have been sending.
func encodeWord(text string) string {
	raw := []byte(text)
	if lenQ(raw)-lenB(raw) < 5 {
		return "=?utf-8?q?" + encodeQ(raw) + "?="
	}
	return "=?utf-8?b?" + base64.StdEncoding.EncodeToString(raw) + "?="
}

// encodedWordOverhead is what "=?utf-8?x?" and "?=" cost around the payload.
const encodedWordOverhead = len("=?utf-8?q?") + len("?=")

func lenQ(raw []byte) int {
	total := 0
	for _, b := range raw {
		total += len(qByte(b))
	}
	return total
}

// lenB is len_b: four characters out for every three bytes in, or part of three.
func lenB(raw []byte) int {
	groups, leftover := len(raw)/3, len(raw)%3
	if leftover > 0 {
		return groups*4 + 4
	}
	return groups * 4
}

func encodeQ(raw []byte) string {
	var b strings.Builder
	for _, c := range raw {
		b.WriteString(qByte(c))
	}
	return b.String()
}

func qByte(c byte) string {
	if c == ' ' {
		return "_"
	}
	if strings.IndexByte(qSafe, c) >= 0 {
		return string(rune(c))
	}
	return "=" + upperHex(c)
}

const hexDigits = "0123456789ABCDEF"

func upperHex(c byte) string {
	return string([]byte{hexDigits[c>>4], hexDigits[c&0x0f]})
}
